Index: hub/src/main/assets/hub/index.html
===================================================================
--- hub/src/main/assets/hub/index.html	
+++ hub/src/main/assets/hub/index.html	
@@ -1,1152 +1,1174 @@
 <!DOCTYPE html>
 <html lang="ru">
 <head>
 <meta charset="utf-8">
 <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
 <meta name="theme-color" content="#0d0d12">
 <title>NPM Hub — запуск</title>
 <style>
   * { box-sizing:border-box; -webkit-tap-highlight-color:transparent; }
   body { margin:0; background:#0d0d12; color:#e8e8f0;
          font:15px/1.5 -apple-system,"Segoe UI",Roboto,sans-serif; padding:20px 16px 40px; }
   .wrap { max-width:480px; margin:0 auto; }
   .logo { font-size:26px; font-weight:800; text-align:center;
           background:linear-gradient(135deg,#58a6ff,#bc8cff);
           -webkit-background-clip:text; -webkit-text-fill-color:transparent; }
   .sub { font-size:13px; color:#8a8a9e; text-align:center; margin:2px 0 18px; }
   label { display:block; font-size:13px; color:#8a8a9e; margin-bottom:12px; }
   input { display:block; width:100%; margin-top:6px; padding:13px 14px; font:inherit;
           color:#e8e8f0; background:#16161f; border:1px solid #262633; border-radius:10px; }
   button { display:block; width:100%; font:inherit; font-weight:700; border:0; border-radius:10px;
            padding:14px; margin:8px 0; cursor:pointer; background:#58a6ff; color:#0d0d12; min-height:50px; }
   button.ghost { background:transparent; color:#58a6ff; border:1px solid #262633; }
   button:disabled { opacity:.5; }
   .log { margin-top:14px; padding:12px 14px; background:#16161f; border:1px solid #262633;
          border-radius:10px; font-size:13px; min-height:60px; }
   .log:empty::before { content:"Здесь будет ход запуска…"; color:#55555f; }
   .err { color:#ff7b72; }
   .ok { color:#3fb950; }
   .note { font-size:12px; color:#55555f; margin-top:12px; text-align:center; }
   .lock { text-align:center; margin:4px 0 14px; }
   .lock .age { font-size:12px; color:#8a8a9e; margin-bottom:10px; }
   .link { display:block; text-align:center; font-size:13px; color:#58a6ff;
           margin:6px 0 0; text-decoration:none; }
   .spacer { height:8px; }

   /* ── tabs ── */
   .tabs { display:flex; gap:8px; margin:0 0 14px; }
   .tab { flex:1; display:block; width:auto; margin:0; padding:11px; min-height:44px;
          font-size:14px; background:#16161f; color:#8a8a9e; border:1px solid #262633; }
   .tab.on { background:#58a6ff; color:#0d0d12; border-color:#58a6ff; }

   /* ── the run indicator: seconds, on purpose ──
      A dispatch is accepted in under a second and then the hub needs one to
      seven minutes. A button that just goes grey for that long is
      indistinguishable from a dead app, so the wait is its own panel with a
      running clock, a bar, and the name of the step GitHub is actually on. */
   .prog { margin:0 0 14px; padding:12px 14px; background:#16161f; border:1px solid #262633;
           border-radius:10px; }
   .prog-top { display:flex; justify-content:space-between; align-items:baseline; gap:10px; }
   .prog-top .lbl { font-size:14px; font-weight:700; }
   .prog-time { font:700 15px/1 ui-monospace,monospace; color:#58a6ff; font-variant-numeric:tabular-nums; }
   .prog.done .prog-time { color:#3fb950; }
   .prog.done { border-color:#1d4429; }
   .prog.fail { border-color:#5c2222; }
   .prog.fail .prog-time { color:#ff7b72; }
   .prog-bar { margin-top:10px; height:5px; border-radius:3px; background:#262633; overflow:hidden; }
   .prog-bar > i { display:block; height:100%; width:0%; background:#58a6ff; transition:width .4s ease; }
   .prog.done .prog-bar > i { background:#3fb950; }
   .prog.fail .prog-bar > i { background:#ff7b72; }
   .prog-stage { margin-top:8px; font-size:12px; color:#8a8a9e; min-height:16px; }
   .prog-act { display:flex; gap:8px; margin-top:10px; }
   .prog-act button { width:auto; flex:0 0 auto; margin:0; padding:8px 12px; min-height:0;
                      font-size:12px; font-weight:600; }

   /* ── cards on the GitHub tab ── */
   .card { margin:0 0 14px; padding:12px 14px; background:#16161f; border:1px solid #262633;
           border-radius:10px; }
   .card-h { display:flex; justify-content:space-between; align-items:center; gap:10px;
             font-size:13px; font-weight:700; color:#e8e8f0; margin-bottom:10px; }
   .card-h button { width:auto; margin:0; padding:7px 11px; min-height:0; font-size:12px; }
   .grid2 { display:grid; grid-template-columns:1fr 1fr; gap:8px; }
   .grid2 button { margin:0; padding:12px 8px; min-height:46px; font-size:13px; }
   .rows { display:flex; flex-direction:column; gap:8px; }
   .row { padding:10px 12px; background:#0f0f16; border:1px solid #262633; border-radius:8px; }
   .row .top { display:flex; justify-content:space-between; align-items:center; gap:8px; }
   .row .nm { font-size:14px; font-weight:700; }
   .row .meta { font-size:11px; color:#8a8a9e; margin-top:3px; font-variant-numeric:tabular-nums; }
   .row .acts { display:flex; gap:6px; margin-top:9px; }
   .row .acts button { width:auto; flex:1; margin:0; padding:9px 6px; min-height:0; font-size:12px; }
   .pill { font-size:10px; padding:2px 7px; border-radius:20px; font-weight:700;
           background:#262633; color:#8a8a9e; }
   .pill.live { background:#1d4429; color:#3fb950; }
   .pill.queue { background:#3d2f0b; color:#d29922; }
   .muted { font-size:12px; color:#55555f; padding:4px 0; }

   /* ── the journal ── */
   .logbar { display:flex; gap:8px; margin-top:16px; }
   .logbar button { width:auto; flex:0 0 auto; margin:0; padding:7px 12px; min-height:0; font-size:12px; }
   .log { margin-top:8px; padding:10px 12px; background:#0f0f16; border:1px solid #262633;
          border-radius:10px; font-size:12px; line-height:1.45; min-height:70px;
          max-height:42vh; overflow-y:auto; -webkit-overflow-scrolling:touch; }
   .log div { padding:1px 0; word-break:break-word; }
   .log .ts { color:#55555f; font-family:ui-monospace,monospace; margin-right:6px;
              font-variant-numeric:tabular-nums; }
   .log .step { color:#bc8cff; }
   .log .err { color:#ff7b72; }
   .log .ok { color:#3fb950; }
 </style>
 </head>
 <body>
 <div class="wrap">
   <div class="logo">◆ NPM Hub</div>
   <div class="sub">Запуск хаба на GitHub Actions</div>

   <div class="tabs">
     <button class="tab on" data-pane="hub">Хаб</button>
     <button class="tab" data-pane="gh">GitHub</button>
   </div>

   <!-- The run indicator. A dispatch is accepted in under a second and the hub
        then needs one to seven minutes; without a clock on screen that is the
        same as a frozen app. -->
   <div id="prog" class="prog" style="display:none">
     <div class="prog-top">
       <span class="lbl" id="prog-label">Запуск…</span>
       <span class="prog-time" id="prog-time">0:00</span>
     </div>
     <div class="prog-bar"><i id="prog-fill"></i></div>
     <div class="prog-stage" id="prog-stage"></div>
     <div class="prog-act" id="prog-act" style="display:none">
       <button class="ghost" id="prog-stop">Прервать ожидание</button>
     </div>
   </div>

   <div id="pane-hub">
   <div id="lockscreen" class="lock" style="display:none">
     <div class="age" id="lockage"></div>
     <button class="ghost" id="lock-open">Подключиться</button>
     <button id="lock-vault">Внешняя память</button>
     <a class="link" href="#" id="lock-settings">Настройки</a>
   </div>
   <label>GitHub-токен (repo + workflow)
     <input id="token" type="password" placeholder="ghp_…" autocomplete="off"
            autocorrect="off" autocapitalize="none" spellcheck="false">
   </label>
   <label>Раннер (пусто = GitHub, иначе метка своего ПК)
     <input id="runner" type="text" placeholder="" autocomplete="off"
            autocorrect="off" autocapitalize="none" spellcheck="false">
   </label>
   <button id="launch">Запустить хаб</button>
   <button id="restart" class="ghost">Остановить и перезапустить ранер</button>
   <button id="reopen" class="ghost" style="display:none">Открыть последний</button>
   <button id="vault" class="ghost">Внешняя память</button>
   </div>

   <!-- The GitHub tab: the same controls the panel has, for the things that
        are started from a phone. Everything here goes through the same
        dispatches the panel uses, so a session started here is indistinguishable
        from one started there. -->
   <div id="pane-gh" style="display:none">
     <div class="card">
       <div class="card-h"><span>Активные сессии</span>
         <button class="ghost" id="gh-refresh">Обновить</button></div>
       <div class="rows" id="gh-sessions"><div class="muted">Нажмите «Обновить».</div></div>
     </div>
     <div class="card">
       <div class="card-h"><span>Запустить</span></div>
       <div class="grid2">
         <button id="run-desks">Стол Windows</button>
         <button id="run-agent" class="ghost">CLI-агент</button>
         <button id="run-opencode" class="ghost">OpenCode</button>
         <button id="run-hub" class="ghost">NPM Hub</button>
       </div>
     </div>
     <div class="card">
       <div class="card-h"><span>Сборки и тесты</span></div>
       <div class="grid2">
         <button id="wf-panel-apk" class="ghost">APK панели</button>
         <button id="wf-hub-apk" class="ghost">APK хаба</button>
         <button id="wf-build" class="ghost">Сборка</button>
         <button id="wf-tests" class="ghost">Тесты</button>
       </div>
     </div>
     <div class="card">
       <div class="card-h"><span>Последние запуски</span></div>
       <div class="rows" id="gh-runs"><div class="muted">Нажмите «Обновить».</div></div>
     </div>
   </div>

   <div class="logbar">
     <button class="ghost" id="log-clear">Очистить журнал</button>
     <button class="ghost" id="log-copy">Копировать</button>
   </div>
   <div id="log" class="log"></div>
   <div class="note">Токен хранится только на этом устройстве.</div>
 </div>
 <script>
 const REPO = 'sj0404-collab/zen-panel';
 const GH = 'https://api.github.com';
 const $ = id => document.getElementById(id);
 const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g,
   c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
 // ── the journal ──
 // Timestamped, and capped. A log without a clock makes "it has been stuck for
 // four minutes" indistinguishable from "it did nothing at all", and a log that
 // only grows is a log nobody scrolls. The last few hundred lines are the ones
 // that describe what is happening right now.
 const LOG_MAX = 500;
 function hhmmss(d) {
   return [d.getHours(), d.getMinutes(), d.getSeconds()]
     .map(n => String(n).padStart(2, '0')).join(':');
 }
 function log(m, cls) {
   const el = $('log');
   if (!el) return;
   const line = document.createElement('div');
   if (cls) line.className = cls;
   const ts = document.createElement('span');
   ts.className = 'ts';
   ts.textContent = hhmmss(new Date());
   line.appendChild(ts);
   line.appendChild(document.createTextNode(String(m == null ? '' : m)));
   el.appendChild(line);
   while (el.childElementCount > LOG_MAX) el.removeChild(el.firstChild);
   el.scrollTop = el.scrollHeight;
 }
 function logStep(m) { log(m, 'step'); }
 function journalText() {
   const el = $('log');
   if (!el) return '';
   return [...el.children].map(l => l.textContent).join('\n');
 }

 // ── the run indicator ──
 // Every long action gets a clock, a bar and a stage line, so the wait is
 // visible and countable instead of a button that quietly greys out.
 let progTimer = null;
 let progAbort = null;
 function mmss(sec) {
   const s = Math.max(0, Math.floor(sec));
   return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0');
 }
 function progStart(label, opts) {
   const o = opts || {};
   const el = $('prog');
   el.className = 'prog';
   el.style.display = '';
   $('prog-label').textContent = label;
   $('prog-stage').textContent = o.stage || 'Отправляю запрос…';
   $('prog-time').textContent = '0:00';
   $('prog-fill').style.width = '4%';
   $('prog-act').style.display = o.cancellable === false ? 'none' : '';
   if (progTimer) clearInterval(progTimer);
   const t0 = Date.now();
   progTimer = setInterval(() => {
     $('prog-time').textContent = mmss((Date.now() - t0) / 1000);
   }, 500);
   return { startedAt: t0, abort: o.cancellable === false ? null : (progAbort = new AbortController()) };
 }
 function progStage(text) {
   const el = $('prog-stage');
   if (el) el.textContent = text || '';
 }
 function progFinish(ok, text) {
   const el = $('prog');
   if (progTimer) { clearInterval(progTimer); progTimer = null; }
   if (progAbort) { progAbort = null; }
   el.className = 'prog ' + (ok ? 'done' : 'fail');
   $('prog-fill').style.width = '100%';
   if (text) progStage(text);
   $('prog-act').style.display = 'none';
   setTimeout(() => { if (el.className.indexOf('fail') >= 0) el.style.display = 'none'; }, 6000);
 }

 // A button has to answer the finger immediately and say what it is doing:
 // pressed, working, done, or failed. Anything else reads as "the app is stuck".
 const busyLabels = new WeakMap();
 function busy(btn, on, text) {
   if (!btn) return;
   if (on) {
     if (!busyLabels.has(btn)) busyLabels.set(btn, btn.textContent);
     btn.disabled = true;
     btn.dataset.busy = '1';
     if (text) btn.textContent = text;
   } else {
     btn.disabled = false;
     delete btn.dataset.busy;
     const back = busyLabels.get(btn);
     if (back != null) btn.textContent = back;
   }
 }
 function isBusy(btn) { return !!(btn && btn.dataset && btn.dataset.busy); }
 function genZt() {
   try { if (window.crypto && crypto.randomUUID) return crypto.randomUUID().replace(/-/g, ''); } catch (e) {}
   const h = '0123456789abcdef';
   let s = '';
   for (let i = 0; i < 32; i++) s += h[Math.floor(Math.random() * 16)];
   return s;
 }
 async function api(path, token, opts) {
   const o = opts || {};
   const r = await fetch(GH + path, {
     method: o.method || 'GET',
     headers: { Accept: 'application/vnd.github+json', Authorization: 'token ' + token },
     body: o.body
   });
   if (r.status === 401) throw new Error('401: токен недействителен. Вставьте новый.');
   if (r.status === 403) {
     const rem = r.headers.get('X-RateLimit-Remaining');
     if (rem === '0') {
       const at = new Date(Number(r.headers.get('X-RateLimit-Reset') || 0) * 1000);
       throw new Error('Лимит API GitHub исчерпан (5000/час). Обнулится в ' + at.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) + ' — дождитесь и запустите снова.');
     }
     throw new Error('403: у токена нет прав. Нужны разрешения repo + workflow (Actions).');
   }
   if (r.status === 429) throw new Error('429: слишком много запросов — подождите минуту.');
   if (r.status === 404) return null;
   if (r.status === 202 || r.status === 204) return true;
   if (!r.ok) throw new Error('HTTP ' + r.status);
   return r.json();
 }
 async function dispatchHub(token, zt, runner, replace) {
   const inputs = { os: 'linux', label: 'hub-apk', token: zt, gh_token: token, replace: replace === true };
   if (runner) inputs.runner_linux = runner;
   await api(`/repos/${REPO}/actions/workflows/hub.yml/dispatches`, token, {
     method: 'POST',
     body: JSON.stringify({ ref: 'main', inputs })
   });
 }
 // Dispatch any workflow in the repo, with the inputs the panel uses for the
 // same thing. A session started from this tab and one started from the panel
 // are then the same run - the panel picks it up by workflow name, not by who
 // pressed the button.
 async function dispatchWorkflow(token, file, inputs) {
   await api(`/repos/${REPO}/actions/workflows/${file}/dispatches`, token, {
     method: 'POST',
     body: JSON.stringify({ ref: 'main', inputs: inputs || {} })
   });
 }

 const RUN_STAGE = {
   queued: 'в очереди GitHub Actions', waiting: 'ждёт раннер', requested: 'запрошен раннер',
   pending: 'ожидает раннера', in_progress: 'идёт'
 };
 const JOB_STAGE = {
   queued: 'ожидание раннера', waiting: 'ожидание раннера', pending: 'ожидание раннера',
   in_progress: 'выполняется', completed: 'завершён'
 };
 // The steps GitHub knows about, in a language a person can read. These are the
 // same names the panel shows, so the journal reads the same wherever it was
 // started from.
 const STEP_RU = {
   'Set up job': 'подготовка',
   'Run actions/checkout@v4': 'получение кода',
   'Mask the gate token in logs': 'маскирование токена',
   'Run actions/setup-node@v4': 'установка Node',
   'Restore the npm/pip caches': 'кэш пакетов',
   'Install the CLI agents': 'установка агентов',
   'Install the hub dependencies': 'зависимости хаба',
   'Install OpenCode for session recovery': 'установка OpenCode',
   'Put zen-agent on PATH': 'установка zen-agent',
   'Create the work folder and restore repositories': 'восстановление репозиториев',
   'Start the hub and open the tunnel': 'запуск хаба и туннеля',
   'Keep the session alive': 'сессия работает',
   'Keep the VNC session alive': 'VNC работает',
   'Start the Linux desktop and open the tunnel': 'запуск рабочего стола',
   'Install the desktop + VNC stack': 'установка рабочего стола',
   'Final durable repository and session backup': 'финальное сохранение',
   'Clear the published session': 'снятие публикации',
   'Snapshot audit/code on exit': 'снимок кода и чата',
   'Save the models snapshot': 'снимок моделей',
   'Record the run in the history': 'запись в историю',
   'Build release APK': 'сборка APK',
   'Package APK': 'упаковка APK',
   'Publish GitHub Release': 'публикация релиза',
   'Restore repositories': 'восстановление репозиториев'
 };
 function stepRu(name) {
   if (!name) return '';
   if (STEP_RU[name]) return STEP_RU[name];
   // Anything this build has never heard of still gets shown, just trimmed:
   // an unknown step is information, a blank line is not.
   return String(name).replace(/^Run\s+/i, '').replace(/@v\d+$/, '').toLowerCase();
 }
 let stopWaiting = false;
 // A top-level `let` is not a property of window, and this one flag is the piece
 // of run state worth being able to see and to poke from the outside - the test
 // suite uses it, and so does anyone debugging a stuck wait from a console.
 Object.defineProperty(window, 'stopWaiting', {
   get: () => stopWaiting,
   set: (v) => { stopWaiting = !!v; }
 });
 // Follow a run until it stops being interesting, narrating every change into
 // the journal and onto the indicator. Returns the run, or null if the user
 // pressed "stop waiting" - which is a normal outcome, not an error.
 async function followRun(token, runId, opts) {
   const o = opts || {};
   const untilLive = o.untilLive === true;
   let lastStep = '';
   for (let i = 0; i < (o.attempts || 240); i++) {
     if (stopWaiting) return null;
     const runs = await api(`/repos/${REPO}/actions/runs?per_page=50`, token);
     const run = runs && (runs.workflow_runs || []).find(r => String(r.id) === String(runId));
     if (!run) {
       if (i > 2) { logStep('Прогон исчез из списка GitHub.'); return null; }
     } else {
       const stage = RUN_STAGE[run.status] || run.status;
       progStage('Прогон #' + run.run_number + ': ' + stage);
       if (untilLive && run.status === 'completed') {
         if (run.conclusion === 'success') return run;
         return run;
       }
       if (!untilLive && run.status === 'completed') return run;
       // The step is what makes a wait legible: "restoring repositories · 42s"
       // says far more than "in progress".
       try {
         const j = await api(`/repos/${REPO}/actions/runs/${runId}/jobs`, token);
         for (const job of (j && j.jobs) || []) {
           const cur = (job.steps || []).find(s => s.status === 'in_progress')
             || (job.steps || [])[(job.steps || []).length - 1];
           if (cur && cur.name && cur.name !== lastStep) {
             lastStep = cur.name;
             const took = cur.started_at
               ? Math.round((Date.now() - new Date(cur.started_at).getTime()) / 1000) : 0;
             logStep('→ ' + (job.name || 'job') + ': ' + stepRu(cur.name) +
               (took ? ' · ' + mmss(took) : ''));
           }
         }
       } catch (e) { /* the run matters more than its steps */ }
     }
     await new Promise(r => setTimeout(r, o.sleepMs || 5000));
   }
   return null;
 }
 async function findFreshRun(token, sinceMs, name) {
   const runs = await api(`/repos/${REPO}/actions/runs?per_page=50`, token);
   const list = (runs && runs.workflow_runs) || [];
   for (const r of list) {
     if (name && r.name !== name) continue;
     const born = Date.parse(r.created_at || '') || 0;
     if (born >= sinceMs - 20000) return r;
   }
   return null;
 }

 const ACTIVE_RUN_STATUSES = ['queued', 'requested', 'waiting', 'in_progress', 'pending'];
 const SESSION_WORKFLOWS = new Set([
   '.github/workflows/hub.yml',
   '.github/workflows/agent.yml',
   '.github/workflows/opencode.yml',
   '.github/workflows/desks.yml'
 ]);
 function isActiveRun(run) {
   return !!run && ACTIVE_RUN_STATUSES.includes(run.status);
 }
 function isHubRun(run) {
   return !!run && (run.path === '.github/workflows/hub.yml' || run.name === 'NPM Hub');
 }
 function isSessionRun(run) {
   return !!run && (SESSION_WORKFLOWS.has(run.path) ||
     ['NPM Hub', 'Zen agent', 'OpenCode', 'opencode', 'Remote session', 'Desks'].includes(run.name));
 }
 async function listActiveRuns(token, predicate) {
   const active = [];
   for (let page = 1; page <= 5; page++) {
     const r = await api(`/repos/${REPO}/actions/runs?per_page=100&page=${page}`, token);
     const runs = r && r.workflow_runs;
     if (!runs || !runs.length) break;
     for (const run of runs) {
       if (isActiveRun(run) && (!predicate || predicate(run))) active.push(run);
     }
     if (runs.length < 100) break;
   }
   return active;
 }
