+  return 'Адрес не отвечает: ' + detail;
+}
 function buildOpenUrl(s, zt, baseOpt) {
   const base = String(baseOpt || s.hubUrl || s.url || '').replace(/\/+$/, '');
   return base + '/m?zt=' + encodeURIComponent(zt);
 }

