    method: o.method || 'GET',
    headers: { Accept: 'application/vnd.github+json', Authorization: 'token ' + token },
    body: o.body
  });
  if (r.status === 401) throw new Error('401: токен недействителен. Вставьте новый.');
  if (r.status === 403) {
    const rem = r.headers.get('X-RateLimit-Remaining');
    if (rem === '0') {
      const at = new Date(Number(r.headers.get('X-RateLimit-Reset') || 0) * 1000);
      throw new Error('Лимит API GitHub исчерпан (5000/час). Обнулится в ' + at.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) + ' — дождитесь и запустите снова.');
