  }
  if (r.status === 429) throw new Error('429: слишком много запросов — подождите минуту.');
  if (r.status === 404) return null;
  if (r.status === 202 || r.status === 204) return true;
  if (!r.ok) throw new Error('HTTP ' + r.status);
  return r.json();
